WFJ.Data.add("book", {
  ["731b84412226678a"] = { "Order of Tirisfalの油断ない監視のもと、Dalaranはこの地の魔術師たちにとって学問の中心地となった。Dalaranを統治するMagocratsはKirin Torを創設した。これは、当時人類に知られていたあらゆる呪文、アーティファクト、魔法の品を目録にまとめ研究することを任務とする専門の一派であった。", "." },
  ["731f724a938bb59e"] = { "これにはさらなる調査が必要かもしれない。死んだ同胞の霊と戦えるほど自分が強いのか、自信がない……ましてやDor'danilの奥深くに踏み込んで柄頭を見つけるなど。\n\n（覚え書き：Astranaarで準備を進めるうちに、最近、ドワーフのハンターに出会った。彼はAshenvaleで長い時間を費やし、我らの民を助けようとしてきた。Stormwindという所から来たそうだ。\n\nある夜、エールを何杯か酌み交わしながら語り合った。彼の話を聞いて、柄頭を見つけられるという新たな希望が湧いてきた……", "." },
  ["733ee1b2d96ba0b7"] = { "彼が最も恐れていたものであった。\n\nLys Ladimore\n最愛の妻にして母\n\nMorganの不安は落胆に、そして悲嘆へと変わり、彼は膝をついて泣き崩れた。何時間も、彼はその一つの墓を見つめ、冷たい石に許しを乞い、すすり泣きながら詫び続けた。そして数時間後、彼の中で何かが切れ、彼は暴れ始めた。鞘から剣を抜き、怒りに叫びながら墓石に次々と打ちかかった。怒りに我を忘れ、やみくもに剣を振り回すうち、その騒ぎは", "." },
  ["73734a8f235f350b"] = { "2日目\nwind stoneの場所については大いに議論になっている。古い予言に記された場所が実際にどこを指すのか、我らの中で最も賢い者でさえ確信をもって判断できないのだ。\n\n私は元の北の一団に残った。我らが正しかったことは、時がたてば必ず証明されるだろう。この場所ではエネルギーの線が有害な角度で交わっている、などという主張は愚かで浅はかだ。\n\nすでに我らは、必要な建材を猛烈な速さで集めている。", "." },
  ["73a0825bfab64249"] = { "オークだけがかかる何か奇妙な病が、この不可解な無気力を引き起こしたのだと推測する者もいた。しかしDalaranのArchmage Antonidasは別の仮説を立てた。オークの歴史について見つけられるわずかな資料を調べたAntonidasは、オークが幾世代にもわたって悪魔の力の破壊的な影響下にあったことを知った。", "." },
  ["73b627d65954adaa"] = { "1日目:\n\n6am～11am - 上のキャンプ\n\n11am～11:30 am - 休憩、昼食\n\n11:30am～4:00pm - 峡谷の道\n\n4:00pm～7:30pm - 上のキャンプ\n\n2日目:\n\n1日目と同じ予定\n\n3日目:\n\n同じ予定\n\n4日目:\n\n同じ予定、ただし1つ例外がある。日没の直前、Thorsenは私に自分の持ち場を任せ、こっそり峡谷の道を下っていった。我々の工作員に会いに行ったのだろうと私は考えた。\n\nだが、奴は一時間後に戻ってきた。これには驚いた。工作員と会ってKurzenのもとへ戻るものと期待していたのだ。何かがおかしい。", "." },
  ["73cf438f8fbb90f8"] = { "古くからの恋人Malfurion Stormrageに呼びかけ、Tyrandeは守りを固めてLegionを押し返すことに成功した。Malfurionの助けにより、自然そのものが立ち上がり、Legionとその同盟者Scourgeを打ち破った。", "." },
  ["73d107a933628e8d"] = { "Eluneは私の願いを聞き届けてくださった。倒れた仲間たちの命は無駄にはならず、私はScythe of Eluneを用いて彼らの死に報いるのだ。それは古い物で、ねじれ節くれだった木の枝であり、Kaldoreiよりもさらに古いものかもしれない。\n\n何時間もかけて、私は女神が授けてくださったこの道具を調べた。それが普通の武器でないことは確かであり、単なる魔法の道具でもない。これを持つと……まるで時間と空間の障壁が弱まるかのようなのだ。\n\nScytheを", "." },
